// Package solarmint is a minimal, disposable single-artwork GRC721-style
// NFT minter -- built purely as a cost test (real signed mint transaction
// on topaz-1, to see what it actually costs), not a production
// collection. Every mint gets the exact same artwork (an animated solar
// system SVG), capped at MaxSupply, paid at a flat MintPriceUgnot per
// mint. Deliberately self-contained (no vendored avl/grc721 package
// dependency, just a plain map) since a 20-token test collection doesn't
// need a full B-tree or the wider GRC721 metadata-editing surface --
// keeps the deploy itself small and cheap, so the image is the only
// real cost driver being measured.
package solarmint

import (
	"chain"
	"chain/banker"
	unsaferealm "chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
)

const (
	CollectionName   = "Solar System Test"
	CollectionSymbol = "SOLARTEST"

	// MaxSupply caps total mints across the whole collection.
	MaxSupply = 20

	// MintPriceUgnot is the flat cost of every mint, in ugnot (0.1 GNOT).
	MintPriceUgnot = 100000
)

var (
	// collectionOwner is this realm's deploy-time owner (informational
	// here -- nothing in this minimal test realm is owner-gated beyond
	// deploy itself, since there's no metadata to curate: every token is
	// identical by design).
	collectionOwner address = "g1n27703259g9ts046dqzly6h6ynp2cuf6hfez3c"

	// paymentRecipient is where mint proceeds are sent. Deliberately a
	// plain address constant, not derived from the deployer/caller --
	// nothing about gno.land requires mint payments to go to whoever
	// published the realm; this is just a banker.SendCoins destination,
	// and could be set to any address at all.
	paymentRecipient address = "g1n27703259g9ts046dqzly6h6ynp2cuf6hfez3c"

	owners     = map[int64]address{}
	tokenCount int64

	// sharedImage is the same data: URI for every single token -- set
	// once in init() from the base64 blob below.
	sharedImage string
)

// svgBase64 is FIG. 117 ("The inclined solar system... Saturn now shown
// with four concentric ring bands... a comet swinging past the sun"), a
// full-fidelity animated SVG including its background starfield,
// base64-encoded so it can sit in a Go string literal without needing to
// escape the SVG's own embedded double quotes.
const svgBase64 = ``

func init(cur realm) {
	sharedImage = "data:image/svg+xml;base64," + svgBase64
}

func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func Name() string      { return CollectionName }
func Symbol() string    { return CollectionSymbol }
func TokenCount() int64 { return tokenCount }
func MaxTokens() int64  { return MaxSupply }
func Owner() address    { return collectionOwner }
func PaymentRecipient() address { return paymentRecipient }
func PriceUgnot() int64 { return MintPriceUgnot }

func OwnerOf(tid int64) address {
	owner, ok := owners[tid]
	if !ok {
		panic("token does not exist")
	}
	return owner
}

func BalanceOf(owner address) int64 {
	var n int64
	for i := int64(1); i <= tokenCount; i++ {
		if owners[i] == owner {
			n++
		}
	}
	return n
}

// TokenURI returns this token's on-chain metadata as a data: URI JSON
// blob, following the OpenSea metadata standard. Only the token's own
// number differs between tokens -- image and description are identical
// for every mint by design (this is an open, same-art-for-everyone
// collection, not a preset queue of distinct pieces).
func TokenURI(tid int64) string {
	if _, ok := owners[tid]; !ok {
		panic("token does not exist")
	}
	return ufmt.Sprintf(
		`{"name":"%s #%d","description":"A shared on-chain solar-system artwork -- every mint in this test collection is identical. Deployed purely as a cost test on topaz-1.","image":"%s"}`,
		CollectionName, tid, sharedImage,
	)
}

// Mint pays MintPriceUgnot and receives the next sequential token,
// owned by whoever signed the transaction. Public -- no allowlist, no
// owner gate. Panics once MaxSupply is reached.
func Mint(cur realm) int64 {
	if tokenCount >= MaxSupply {
		panic("max supply reached")
	}
	if !unsaferealm.PreviousRealm().IsUserCall() {
		panic("mint must come from a direct user call")
	}
	sent := unsaferealm.OriginSend()
	var total int64
	for _, c := range sent {
		if c.Denom == "ugnot" {
			total += c.Amount
		}
	}
	if total < MintPriceUgnot {
		panic(ufmt.Sprintf("insufficient payment: mint costs %d ugnot, got %d", MintPriceUgnot, total))
	}
	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	banker_.SendCoins(cur.Address(), paymentRecipient, chain.Coins{chain.NewCoin("ugnot", MintPriceUgnot)})

	tokenCount++
	tid := tokenCount
	owners[tid] = callerAddress()
	return tid
}

func Render(path string) string {
	return ufmt.Sprintf(
		"# %s\n\nA disposable cost-test NFT collection -- every mint is the same shared artwork.\n\n* **Minted**: %d / %d\n* **Price**: %d ugnot per mint\n* **Payment goes to**: %s\n",
		CollectionName, tokenCount, int64(MaxSupply), int64(MintPriceUgnot), paymentRecipient,
	)
}
